<section><div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3"><?= h($service['hostname'] ?: '云主机详情') ?></h1><a class="btn btn-outline-success" href="<?= h(url_to('index/host/renew', ['id' => $service['id']])) ?>">续费</a></div><div class="card p-4 mb-3"><div class="row g-3"><div class="col-sm-6"><div class="text-muted">IP 地址</div><div class="copy-box mono"><?= h($service['ip'] ?: '分配中') ?></div></div><div class="col-sm-6"><div class="text-muted">状态 / 到期</div><div><?= status_badge($service['status'], 'service') ?> · <?= h($service['due_time'] ? date('Y-m-d H:i', $service['due_time']) : '—') ?></div></div><div class="col-sm-6"><div class="text-muted">账号</div><div class="copy-box mono"><?= h($service['username'] ?: 'root') ?></div></div><div class="col-sm-6"><div class="text-muted">密码</div><div class="copy-box mono"><?= h($password ?: '暂不可用') ?></div></div></div><?php if ($service['last_error']): ?><div class="alert alert-warning mt-3 mb-0"><?= h($service['last_error']) ?></div><?php endif; ?></div><div class="mobile-stack mb-3"><form method="post" action="<?= h(url_to('index/host/action')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$service['id'] ?>"><button name="action" value="on" class="btn btn-outline-primary">开机</button><button name="action" value="off" class="btn btn-outline-secondary">关机</button><button name="action" value="reboot" class="btn btn-outline-primary">重启</button><button name="action" value="reinstall" class="btn btn-outline-warning">重装</button><button name="action" value="reset_password" class="btn btn-outline-warning">重置密码</button></form><a class="btn btn-outline-primary" href="<?= h(url_to('index/host/upgrade', ['id' => $service['id']])) ?>">升级配置</a></div><div class="card p-4"><h2 class="h5">取消申请</h2><form method="post" action="<?= h(url_to('index/host/cancel')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$service['id'] ?>"><div class="row g-2"><div class="col-md-3"><select name="mode" class="form-select"><option value="end">到期取消</option><option value="immediate">立即取消</option></select></div><div class="col-md-6"><input name="reason" class="form-control" placeholder="申请原因"></div><div class="col-md-3"><button class="btn btn-outline-danger w-100">提交申请</button></div></div></form><?php if ($cancel): ?><div class="small text-muted mt-3">申请状态：<?= status_badge($cancel['status'], 'cancel') ?><?php if ($cancel['status'] === 'pending'): ?><form class="d-inline" method="post" action="<?= h(url_to('index/host/withdrawCancel')) ?>"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int)$cancel['id'] ?>"><button class="btn btn-sm btn-link">撤回</button></form><?php endif; ?></div><?php endif; ?></div></section>
